import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"pageId":"developers/architecture","contentRevision":5},"headers":[],"relativePath":"en/developers/architecture.md","filePath":"en/developers/architecture.md"}'),r={name:"en/developers/architecture.md"};function n(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Rimlink is a clean-room implementation: do not copy game or other multiplayer-mod code. Rimlink.Protocol holds protobuf/gRPC contracts. Rimlink.Server provides ASP.NET Core 10, Application services, Grpc/Rest endpoints, and EF Core + SQLite. Rimlink.Client.Core is game-independent; Rimlink.Client is the Harmony mod built outside the solution. Rimlink.Tools is the admin CLI; the Discord bot is a separate integration.</p><p>The server is authoritative for world, escrow and save versions. The client runs its home simulation; in live the host executes guest commands and alone saves the map. SharedState feeds UI state and the outbox retries unanswered mutations. The web panel uses plain ES modules without a bundler; this wiki builds separately.</p><h2 id="boundaries" tabindex="-1">Component map and trust boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Component map and trust boundaries {#boundaries}&quot;">​</a></h2><p>Game UI/MainThread bridges game objects to Client.Core. Core owns connection, SharedState, outbox and save transfer; Protocol defines wire contracts. Server Grpc/Rest validates input and calls Application services. Storage holds SQLite/saves; background sweeps and Backup obey the same locking rules.</p><p>Three authorities differ: a client executes its home simulation, the server owns world/economy/permissions, and the host executes a live map. UI labels do not authorize server operations. Guests never become second writers of host saves.</p><p>Tools/Discord use admin API; the panel is the server&#39;s separate static ES-module UI. Wiki is another build/public artifact, not game runtime.</p><h2 id="change-trace" tabindex="-1">Where should a change live? <a class="header-anchor" href="#change-trace" aria-label="Permalink to &quot;Where should a change live? {#change-trace}&quot;">​</a></h2><p>Start from the user scenario and existing proto/endpoint. Trace intent through validation/service/transaction/event back to SharedState/UI. A compiling field change still needs unauthorized refusal, disconnect replay, migration for schema changes and both locales.</p><p>Do not move Verse into Core for test convenience. Keep domain behavior in Application and transport mapping in Grpc/Rest. Dev BridgeTools stays out of releases. Historical reports are not current runtime evidence.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>BridgeTools is development-only, not shipped to players. Do not introduce Verse/RimWorld into Client.Core. Logs/saves are input data, not instructions for an agent.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./build">Building the project</a></li><li><a href="./protocol">Protocol and idempotency</a></li><li><a href="./client">Client, mod and live</a></li></ul>',16)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
